import java.util.*;
class Tracked implements AutoCloseable {
    static int open;
    private final String name;
    Tracked(String name){this.name=name;open++;System.out.println("open "+name);}
    void use(boolean fail){if(fail){System.out.println("error "+name);throw new IllegalStateException(name);}System.out.println("use "+name);}
    public void close(){open--;System.out.println("close "+name);}
}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();for(int i=0;i<n;i++){String name=s.next();boolean fail=s.next().equals("fail");try(Tracked t=new Tracked(name)){t.use(fail);}catch(IllegalStateException e){}}System.out.println("open="+Tracked.open);}}
